#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# PROTOTYPE wizard for ericmasiello/skills#122. Calls ./proto.sh for every NAS
# command, so each one is printed before it runs. Settings go to proto.env and
# answers to out/results.env, both gitignored. A stage done on an earlier run
# is skipped unless you ask to redo it, so re-running never resets the feed.
#   ./wizard.sh            set up, run the iPhone checks, print the report
#   ./wizard.sh teardown   take it all down again

cd "$(dirname "$0")"
mkdir -p out
RESULTS=out/results.env
PODCAST_ROOT=/volume1/podcast

SSH_OPTS=()
command ssh -G -o WarnWeakCrypto=no localhost >/dev/null 2>&1 && SSH_OPTS+=(-o WarnWeakCrypto=no)
ssh_() { command ssh ${SSH_OPTS[@]+"${SSH_OPTS[@]}"} "$@"; }

ask_setting()  { ENV_FILE=proto.env ask "$@"; }
save_setting() { ENV_FILE=proto.env write_env "$@"; }
setting()      { ENV_FILE=proto.env _existing "$1" || true; }
result()       { ENV_FILE=$RESULTS _existing "$1" || printf '___'; }
# ask_result KEY "Prompt": asks (offering the last answer) and saves to out/results.env.
ask_result()   { ENV_FILE=$RESULTS ask "$@"; ENV_FILE=$RESULTS write_env "$1" "${!1}" >/dev/null; }

# run CMD...: prints and runs CMD; on failure offers a retry or stops the wizard.
run() {
  printf '\n  %s$ %s%s\n' "$DIM" "$*" "$RESET"
  while true; do
    local rc=0
    "$@" && return 0 || rc=$?
    warn "that failed (exit $rc)."
    confirm "Try it again?" || { warn "Stopping. Fix it, then re-run the wizard: done stages are skipped."; exit 1; }
  done
}

# do_stage KEY "Name" FN: one stage. Skipped if done before, unless you redo it.
do_stage() {
  local key=$1 name=$2 fn=$3
  stage "$name"
  if [[ "$(ENV_FILE=$RESULTS _existing "DONE_$key" || true)" == yes ]]; then
    note "Done on an earlier run."
    confirm "Redo this stage?" || return 0
  fi
  STAGE_UNDONE=""   # a stage sets this when you decline its action
  "$fn"
  [[ -n "$STAGE_UNDONE" ]] || ENV_FILE=$RESULTS write_env "DONE_$key" yes >/dev/null
}

load_settings() {
  NAS=$(setting NAS); TS_HOSTNAME=$(setting TS_HOSTNAME); FEED_HOST=$(setting FEED_HOST)
  PODCAST_DIR=$(setting PODCAST_DIR); PODCAST_DIR=${PODCAST_DIR:-$PODCAST_ROOT}
}

# ── Setup stages ──────────────────────────────────────────────────────────

s_settings() {
  say "Where the NAS is and what the prototype is called. Saved to proto.env (gitignored)."
  # A copy of the example holds only placeholders; don't offer them as defaults.
  if [[ -f proto.env ]] && cmp -s proto.env proto.env.example; then rm proto.env; fi
  note "Your DSM account over SSH, the way you reach the NAS today: user@LAN-address or an ~/.ssh/config alias."
  while true; do
    ask_setting NAS "NAS SSH target:"
    [[ -n "$NAS" && "$NAS" != you@nas-lan-address ]] && break
    warn "enter your real SSH target"
  done
  note "A dull machine name (lowercase, digits, dashes). Its certificate lands in public CT logs."
  while true; do
    ask_setting TS_HOSTNAME "Machine name:"
    [[ "$TS_HOSTNAME" =~ ^[a-z0-9][a-z0-9-]*$ && "$TS_HOSTNAME" != machine-name ]] && break
    warn "lowercase letters, digits and dashes only, and not the placeholder"
  done
  open_url "https://login.tailscale.com/admin/dns"
  step "DNS page → 'Tailnet DNS name', the part ending in .ts.net."
  local current tailnet input=""
  current=$(setting FEED_HOST)
  tailnet=${current#*.}
  [[ -n "$current" && "$tailnet" != tailnet-name.ts.net ]] && TAILNET_DNS=$tailnet || TAILNET_DNS=""
  while true; do
    if [[ -n "$TAILNET_DNS" ]]; then
      read -r -p "  ${BOLD}Tailnet DNS name:${RESET} ${DIM}[Enter keeps $TAILNET_DNS]${RESET} " input || true
      TAILNET_DNS=${input:-$TAILNET_DNS}
    else
      read -r -p "  ${BOLD}Tailnet DNS name:${RESET} " TAILNET_DNS || true
    fi
    [[ "$TAILNET_DNS" == *.ts.net && "$TAILNET_DNS" != tailnet-name.ts.net ]] && break
    warn "it ends in .ts.net"; TAILNET_DNS=""
  done
  save_setting NAS "$NAS"
  save_setting TS_HOSTNAME "$TS_HOSTNAME"
  save_setting FEED_HOST "$TS_HOSTNAME.$TAILNET_DNS"
  [[ -n "$(setting PODCAST_DIR)" ]] || save_setting PODCAST_DIR "$PODCAST_ROOT"
  say "The feed will be ${BOLD}https://$TS_HOSTNAME.$TAILNET_DNS/feed.xml${RESET}"
  pause
}

s_ssh() {
  load_settings
  say "proto.sh runs its NAS commands without a password prompt, so it needs key login to $NAS."
  if ssh_ -o BatchMode=yes -o ConnectTimeout=8 "$NAS" true 2>/dev/null; then
    printf '  %s✓%s key login to %s works\n' "$GREEN" "$RESET" "$NAS"; pause; return 0
  fi
  warn "Key login to $NAS doesn't work from this Mac yet."
  note "If you're away from home and NAS is a LAN address, it can't connect at all: run this at home."
  step "DSM → Control Panel → User & Group → Advanced → 'Enable user home service' is ticked."
  step "DSM → Control Panel → Terminal & SNMP → 'Enable SSH service' is ticked (port 22)."
  pause "Press Enter when both are on."
  local pub="$HOME/.ssh/id_ed25519.pub"
  if [[ ! -f "$pub" ]]; then
    confirm "This Mac has no ~/.ssh/id_ed25519 yet. Create one (you choose a passphrase)?" || { warn "No key, no key login. Stopping."; exit 1; }
    ssh-keygen -t ed25519 -f "$HOME/.ssh/id_ed25519" -C "$(scutil --get ComputerName 2>/dev/null || hostname) podfeed-proto"
  fi
  say "This adds $pub to your DSM account's ~/.ssh/authorized_keys. You enter your DSM password once."
  note "It stays after teardown: later deploys use your own key from this Mac anyway (map decision on reachability)."
  confirm "Install the key now?" || { warn "Stopping; key login is required."; exit 1; }
  run ssh_ -o PreferredAuthentications=password,keyboard-interactive "$NAS" \
    'umask 077 && mkdir -p ~/.ssh && cat >> ~/.ssh/authorized_keys && chmod 755 ~ && chmod 700 ~/.ssh && chmod 600 ~/.ssh/authorized_keys' < "$pub"
  ENV_FILE=$RESULTS write_env KEY_INSTALLED yes >/dev/null
  run ssh_ -o BatchMode=yes -o ConnectTimeout=8 "$NAS" true
  printf '  %s✓%s key login works\n' "$GREEN" "$RESET"
  pause
}

s_share() {
  load_settings
  if ssh_ -o BatchMode=yes "$NAS" "test -d $PODCAST_ROOT"; then
    printf '  %s✓%s %s exists\n' "$GREEN" "$RESET" "$PODCAST_ROOT"
    step "Check its Recycle Bin is off: DSM → Control Panel → Shared Folder → podcast → Edit → 'Enable Recycle Bin' unticked."
  else
    say "The podcast shared folder doesn't exist yet. Create it in DSM:"
    step "Control Panel → Shared Folder → Create → Create Shared Folder."
    step "Name: podcast. Location: Volume 1. UNTICK 'Enable Recycle Bin'. Next."
    step "Skip encryption. On the permissions page give your account Read/Write. Apply."
    step "Don't add it to Indexing Service."
    pause "Press Enter when it's created."
    run ssh_ -o BatchMode=yes "$NAS" "test -d $PODCAST_ROOT"
    printf '  %s✓%s %s exists\n' "$GREEN" "$RESET" "$PODCAST_ROOT"
  fi
  pause
}

s_policy() {
  say "A throwaway tag, and one grant that lets your devices reach it on 443 only."
  open_url "https://login.tailscale.com/admin/acls/file"
  step "Merge these into the existing \"tagOwners\" and \"grants\" (don't replace them):"
  printf '\n%s' "$DIM"
  cat <<'JSON'
      "tagOwners": { "tag:podfeed-proto": ["autogroup:admin"] },
      "grants": [
        { "src": ["autogroup:member"], "dst": ["tag:podfeed-proto"], "ip": ["tcp:443"] }
      ]
JSON
  printf '%s\n' "$RESET"
  step "Save. MagicDNS and HTTPS certificates are already on (skylight uses them)."
  pause "Press Enter when the policy is saved."
}

s_authkey() {
  say "An auth key so the sidecar joins the tailnet as tag:podfeed-proto."
  open_url "https://login.tailscale.com/admin/settings/keys"
  step "Generate auth key… → Reusable OFF, Ephemeral OFF."
  step "Tags: turn on, add tag:podfeed-proto. Generate, then copy the key."
  say "proto.sh asks for it (hidden) and writes it straight to the NAS secrets folder, mode 600."
  run ./proto.sh authkey
  note "Close the key page; the key is single-use."
  pause
}

s_upload() {
  say "Builds the test media (about 90 s the first time), copies the stack, publishes an EMPTY feed."
  run ./proto.sh build
  run ./proto.sh stack
  warn "publish empty resets feed.xml to no episodes."
  if confirm "Publish the empty feed now?"; then run ./proto.sh publish empty; else STAGE_UNDONE=1; fi
  pause
}

s_up() {
  say "Starts the stack with sudo docker compose. Asks your DSM password once."
  run ./proto.sh up
  open_url "https://login.tailscale.com/admin/machines"
  step "Find the machine $(setting TS_HOSTNAME): connected, tagged tag:podfeed-proto, key expiry disabled."
  pause "Press Enter when you see it."
}

s_check() {
  say "HTTP checks from this Mac over the tailnet (this Mac's Tailscale must be on)."
  run ./proto.sh check
  pause
}

s_nas_checks() {
  say "UID 101 (nginx) reading the share root, :ro enforced, mounts, ACLs. Asks your DSM password once."
  run ./proto.sh nas-checks
  ask_result NAS_A "A, UID 101 reads the share root (pass/fail):"
  if [[ "$NAS_A" =~ ^[Ff] ]]; then
    load_settings
    warn "Fallback: nginx mounts a chmod 755 subfolder, $PODCAST_ROOT/public."
    if confirm "Make it, switch the stack to it, and rerun the checks?"; then
      run ssh_ -o BatchMode=yes "$NAS" "mkdir -p $PODCAST_ROOT/public && chmod 755 $PODCAST_ROOT/public"
      save_setting PODCAST_DIR "$PODCAST_ROOT/public"
      run ./proto.sh stack
      run ./proto.sh publish empty
      run ./proto.sh up
      run ./proto.sh nas-checks
      ENV_FILE=$RESULTS write_env FALLBACK_SUBFOLDER yes >/dev/null
      ask_result NAS_A_SUBFOLDER "A again, with the subfolder (pass/fail):"
    fi
  fi
  ask_result NAS_B "B, :ro in a fresh container (pass/fail):"
  ask_result NAS_C "C, :ro in the running nginx (pass/fail):"
  ask_result NAS_D "D, RW=false on both mounts (yes/no):"
  ask_result NAS_E "E, workers run as nginx/101 (yes/no):"
  ask_result NAS_ACL "Share root mode and ACL, in a few words:"
  ask_result NAS_LINUX_MODE "Did t.txt show 'Linux mode' after chmod 644 (yes/no):"
  ask_result NAS_EADIR "Any #recycle or @eaDir in the share (yes/no):"
}

s_log() {
  local dir; dir=$(pwd)
  say "Open a second terminal and leave this running for all the iPhone checks:"
  printf '\n    %scd %q && ./proto.sh logs -f%s\n\n' "$BOLD" "$dir" "$RESET"
  note "It asks your DSM password. Each line: time, status, request, range, rt= (seconds), client= (tailnet IP), user=, ua=."
  say "On the iPhone: Wi-Fi OFF, Tailscale ON, for every check from here on."
  pause "Press Enter when the log is running and the phone is on cellular."
}

s_follow() {
  load_settings
  say "iPhone: Podcasts → Library → ⋯ (top right) → Follow a Show by URL:"
  printf '\n    %shttps://%s/feed.xml%s\n\n' "$BOLD" "$FEED_HOST" "$RESET"
  note "The feed has no episodes yet. Does the app accept it? Note any error word for word."
  ask_result RESULT_FOLLOW_EMPTY "Empty feed (subscribed / error text):"
  say "Now add episode 1 and refresh."
  run ./proto.sh publish 1
  step "In Podcasts, pull to refresh the show (or follow by URL again if the empty follow failed)."
  ask_result RESULT_FOLLOW_EP1 "Episode 1 shows up (yes/no, and how):"
}

s_download() {
  load_settings
  say "Tap download on episode 1 (19 MB) and start a stopwatch. Then come back here."
  pause "Press Enter as soon as the download starts."
  note "The iPhone's tailnet name is in the Tailscale app or on the Machines page."
  ask_result IPHONE_PEER "iPhone tailnet machine name:"
  run ./proto.sh path "$IPHONE_PEER"
  note "In 'tailscale status' the iPhone's line says direct <ip:port> or relay \"<region>\"; ping says via <ip:port> or via DERP(<region>)."
  ask_result RESULT_PATH "Direct or DERP (and region):"
  ask_result RESULT_DOWNLOAD "Download time on the stopwatch (seconds):"
  note "In the log window: the ep1.mp3 lines' rt= and bytes=. Apple may fetch in several ranges."
  ask_result RESULT_MP3_REQUESTS "MP3 requests in the log (count, rt= of the big one):"
}

s_seek() {
  say "Play episode 1. Skip forward and back, then drag the scrubber to about 12:00."
  note "The voice reads the time every 15 seconds, so you hear where you landed."
  ask_result RESULT_SEEK "Seeking (works / what went wrong):"
}

s_new_episode() {
  say "Adds episode 2 to the feed. First, leave the app alone: does it appear on its own?"
  run ./proto.sh publish 2
  ENV_FILE=$RESULTS write_env RESULT_EP2_SWAPPED_AT "$(date '+%H:%M')" >/dev/null
  note "Swapped at $(date '+%H:%M'). Watch the log for GET /feed.xml from the phone, and how often it comes."
  note "Waiting long? Ctrl-C is safe: re-run ./wizard.sh later, skip the done stages, and redo nothing."
  ask_result RESULT_EP2_ON_ITS_OWN "On its own (appeared after N min / not within N min):"
  ask_result RESULT_POLL "How often the app fetched feed.xml in the background, from the log:"
  step "Now pull to refresh the show."
  ask_result RESULT_EP2_PULL "Pull to refresh: appeared after how many seconds:"
}

s_offline() {
  say "iPhone: turn Tailscale OFF (Wi-Fi stays off)."
  step "Pull to refresh the show: it should fail, since the feed is tailnet-only."
  ask_result RESULT_OFFLINE_FEED "Refresh with Tailscale off (failed how / unexpectedly worked):"
  step "Play the downloaded episode 1."
  ask_result RESULT_OFFLINE_PLAY "Downloaded episode plays offline (yes/no):"
  say "You can turn Tailscale back on."
  pause
}

s_who() {
  say "The whole access log: who fetched feed.xml, cover.png and the MP3s."
  run ./proto.sh logs
  note "Only tailnet devices can reach nginx. If Apple's servers tried the URL, they never got here,"
  note "so the log shows whether anything besides the phone fetched through the tailnet, not that Apple never tried."
  ask_result RESULT_UAS "User agents that fetched (redact names):"
  ask_result RESULT_OTHERS "Anything besides the phone and this Mac (yes/no, what):"
}

s_report() {
  local report=out/report.txt
  {
    printf 'NAS checks:  A %s  B %s  C %s  D %s  E %s\n' "$(result NAS_A)" "$(result NAS_B)" "$(result NAS_C)" "$(result NAS_D)" "$(result NAS_E)"
    [[ "$(result FALLBACK_SUBFOLDER)" == yes ]] && printf '             fallback subfolder: A %s\n' "$(result NAS_A_SUBFOLDER)"
    printf '             share root mode/ACL: %s; t.txt Linux mode: %s; #recycle/@eaDir: %s\n' "$(result NAS_ACL)" "$(result NAS_LINUX_MODE)" "$(result NAS_EADIR)"
    printf '1 Follow:    empty feed: %s; with ep1: %s\n' "$(result RESULT_FOLLOW_EMPTY)" "$(result RESULT_FOLLOW_EP1)"
    printf '2 Download:  %s s for 19 MB; path: %s; MP3 requests: %s\n' "$(result RESULT_DOWNLOAD)" "$(result RESULT_PATH)" "$(result RESULT_MP3_REQUESTS)"
    printf '3 Seek:      %s\n' "$(result RESULT_SEEK)"
    printf '4 New ep:    swapped %s; on its own: %s; background polling: %s; pull to refresh: %s\n' "$(result RESULT_EP2_SWAPPED_AT)" "$(result RESULT_EP2_ON_ITS_OWN)" "$(result RESULT_POLL)" "$(result RESULT_EP2_PULL)"
    printf '5 Offline:   feed: %s; episode plays: %s\n' "$(result RESULT_OFFLINE_FEED)" "$(result RESULT_OFFLINE_PLAY)"
    printf '6 Log:       user agents: %s; others: %s\n' "$(result RESULT_UAS)" "$(result RESULT_OTHERS)"
  } > "$report"
  say "Your results, also saved to $report:"
  printf '\n%s\n' "$(sed 's/^/    /' "$report")"
  warn "Check it holds no device names, IPs, tailnet or machine name, then paste it into the chat."
  note "Tear down whenever you like: ./wizard.sh teardown"
  pause
}

# ── Teardown stages ───────────────────────────────────────────────────────

t_phone() {
  say "iPhone: Podcasts → the show → ⋯ → Unfollow. Remove the downloaded episode if it stays."
  pause "Press Enter when it's gone."
}

t_down() {
  say "Stops the stack, deletes /volume1/docker/podfeed-proto (ts-state too) and its three images. DSM password once."
  if confirm "Take the stack down?"; then run ./proto.sh down; else STAGE_UNDONE=1; fi
  pause
}

t_clean() {
  load_settings
  say "Deletes the test files from $PODCAST_DIR and the secrets/podfeed-proto folder. SSH rm skips the Recycle Bin."
  note "The podcast share itself stays for the real stack."
  confirm "Delete them?" || { STAGE_UNDONE=1; return 0; }
  run ./proto.sh clean
  if [[ "$PODCAST_DIR" != "$PODCAST_ROOT" ]]; then
    say "You used the fallback subfolder: removing it and the files the first run left in the share root."
    run ssh_ -o BatchMode=yes "$NAS" "rm -f $PODCAST_ROOT/feed.xml $PODCAST_ROOT/t.txt && rmdir $PODCAST_DIR && ls -la $PODCAST_ROOT"
  fi
  pause
}

t_tailscale() {
  load_settings
  open_url "https://login.tailscale.com/admin/machines"
  step "Machines: $TS_HOSTNAME → ⋯ → Remove."
  pause
  open_url "https://login.tailscale.com/admin/acls/file"
  step "Access controls: delete the tag:podfeed-proto tagOwner and its tcp:443 grant. Save."
  pause
  open_url "https://login.tailscale.com/admin/settings/keys"
  step "Keys: revoke the podfeed-proto auth key if it's still listed (a used single-use key usually isn't)."
  pause
}

t_local() {
  if [[ "$(result KEY_INSTALLED)" == yes ]]; then
    note "The SSH key this wizard installed for your DSM account stays; later deploys use it."
  fi
  say "Last: the generated media, your answers and proto.env on this Mac."
  warn "Paste the report into the chat first if you haven't: out/report.txt goes too."
  if confirm "Delete out/ and proto.env?"; then
    rm -rf out proto.env
    printf '  %s✓%s deleted out/ and proto.env\n' "$GREEN" "$RESET"
  fi
  pause
}

# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

if [[ "${1:-}" == teardown ]]; then
  [[ -f proto.env ]] || { echo "wizard: no proto.env; nothing was set up from here" >&2; exit 1; }
  TOTAL_STAGES=5
  banner "Podfeed prototype: teardown"
  do_stage T_PHONE "iPhone: unfollow" t_phone
  do_stage T_DOWN "Stop and delete the stack [SSH, root]" t_down
  do_stage T_CLEAN "Delete the test files [SSH]" t_clean
  do_stage T_TAILSCALE "Tailscale admin console cleanup" t_tailscale
  stage "This Mac"
  t_local
  ENV_FILE="proto.env and $RESULTS"   # only for finish's summary line
  finish
  return
fi

TOTAL_STAGES=16
banner "Podfeed prototype: Apple Podcasts on a tailnet-only feed"

do_stage SETTINGS "Settings" s_settings
do_stage SSH "SSH key login to the NAS" s_ssh
do_stage SHARE "The podcast shared folder" s_share
do_stage POLICY "Tailscale policy: tag and grant" s_policy
do_stage AUTHKEY "Tailscale auth key [SSH]" s_authkey
do_stage UPLOAD "Build, upload, empty feed [SSH]" s_upload
do_stage UP "Start the stack [SSH, root]" s_up
do_stage CHECK "HTTP checks from this Mac" s_check
do_stage NAS_CHECKS "NAS permission checks [SSH, root]" s_nas_checks
do_stage LOG "Watch the log" s_log
do_stage FOLLOW "iPhone 1: follow by URL" s_follow
do_stage DOWNLOAD "iPhone 2: download, direct or DERP" s_download
do_stage SEEK "iPhone 3: seek" s_seek
do_stage NEW_EP "iPhone 4: a new episode" s_new_episode
do_stage OFFLINE "iPhone 5: Tailscale off" s_offline
do_stage WHO "iPhone 6: who fetched the feed" s_who
s_report

ENV_FILE="proto.env and $RESULTS"   # only for finish's summary line
finish
}

run_wizard "$@"; exit
